insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('PCV13','PCV13','วัคซีนปอดบวม 13 สายพันธุ์','6M','CHOICE_PCV',2000,'ACTIVE','PCV',17,'เข็มที่ 3','วัคซีนป้องกันโรคปอดอักเสบ หูชั้นกลางอักเสบ และโรครุนแรงจากเชื้อนิวโมคอคคัส','เริ่มอายุ 2 เดือน รับตามกำหนดอายุ 2,4,6 และกระตุ้นที่ 12–15 เดือน /หลัง 6 เดือน: 3 เข็ม เช่น 7, 9, 12–15 เดือน / เริ่มหลัง 1 ปี: 2 เข็ม เช่น 13, 15 เดือน / เริ่มหลัง 2 ปี: 1 เข็ม','แนะนำรับให้ครบตามช่วงอายุ เพื่อป้องกันโรคติดเชื้อรุนแรงจากเชื้อนิวโมคอคคัส','หากเริ่มช้าหรือเคยรับบางเข็มแล้ว ควรให้แพทย์ตรวจสมุดวัคซีนก่อนจัดตารางต่อ','Routine','PCV13') on conflict (vaccine_id) do nothing;
insert into vaccines (vaccine_id,name,name_th,age_group,category,price,status,group_code,display_order,dose_name,description,catch_up,recommendation,warning,priority,product_code) values ('PCV15','PCV15','วัคซีนปอดบวม 15 สายพันธุ์','6M','CHOICE_PCV',2700,'ACTIVE','PCV',18,'เข็มที่ 3','วัคซีนป้องกันโรคปอดอักเสบ หูชั้นกลางอักเสบ และโรครุนแรงจากเชื้อนิวโมคอคคัส','เริ่มอายุ 2 เดือน รับตามกำหนดอายุ 2,4,6 และกระตุ้นที่ 12–15 เดือน /หลัง 6 เดือน: 3 เข็ม เช่น 7, 9, 12–15 เดือน / เริ่มหลัง 1 ปี: 2 เข็ม เช่น 13, 15 เดือน / เริ่มหลัง 2 ปี: 1 เข็ม','แนะนำรับให้ครบตามช่วงอายุ เพื่อป้องกันโรคติดเชื้อรุนแรงจากเชื้อนิวโมคอคคัส','หากเริ่มช้าหรือเคยรับบางเข็มแล้ว ควรให้แพทย์ตรวจสมุดวัคซีนก่อนจัดตารางต่อ','Routine','PCV15') on conflict (vaccine_id) do nothing;
