insert into vaccine_rules (rule_id,vaccine_group,product_code,min_age_months,max_age_months,primary_doses,interval_days,booster_rule,eligibility,requires_history,doctor_review,display_message,status,sort_order,scenario_code) values ('RABIES_RIG_REVIEW','RABIES','RABIES_RIG',0,NULL,NULL,NULL,'ให้แพทย์ประเมินโดยเร่งด่วน','มีบาดแผลเสี่ยงสูงและไม่เคยรับวัคซีน รับไม่ครบ จำประวัติไม่ได้ หรือมีภูมิคุ้มกันบกพร่อง',true,'YES','แพทย์จะประเมินความจำเป็นของอิมมูโนโกลบูลินตามลักษณะบาดแผล ประวัติวัคซีน และภาวะภูมิคุ้มกัน','ACTIVE',64,NULL) on conflict (rule_id) do nothing;
insert into vaccine_rules (rule_id,vaccine_group,product_code,min_age_months,max_age_months,primary_doses,interval_days,booster_rule,eligibility,requires_history,doctor_review,display_message,status,sort_order,scenario_code) values ('HBV_1M_MATERNAL_CARRIER','HEPATITIS_B','HBV',1,1,1,NULL,'รับวัคซีนตามตารางต่อเนื่อง','ทารกอายุประมาณ 1 เดือนที่มารดาเป็นพาหะไวรัสตับอักเสบบี หรือแพทย์กำหนดให้รับเพิ่มเติม',true,'YES','อาจต้องรับวัคซีนตับอักเสบบีเพิ่มเติมเมื่ออายุประมาณ 1 เดือน และรับวัคซีนตามตารางต่อเนื่อง โดยแพทย์ตรวจสอบการป้องกันหลังคลอดและประวัติวัคซีนเดิม','ACTIVE',70,NULL) on conflict (rule_id) do nothing;
insert into vaccine_rules (rule_id,vaccine_group,product_code,min_age_months,max_age_months,primary_doses,interval_days,booster_rule,eligibility,requires_history,doctor_review,display_message,status,sort_order,scenario_code) values ('MEN_ACWY_DOCTOR_REVIEW','MENINGOCOCCAL','MEN_ACWY',0,NULL,NULL,NULL,'ประเมินตามอายุและภาวะเสี่ยง','ผู้เดินทางไปพื้นที่เสี่ยง มีข้อกำหนดการเดินทาง มีโรคประจำตัว หรือแพทย์พิจารณา',true,'YES','วัคซีน MenACWY มีเกณฑ์แตกต่างตามอายุ การเดินทาง และภาวะเสี่ยง กรุณาปรึกษาแพทย์เพื่อกำหนดจำนวนเข็มและช่วงเวลาที่เหมาะสม','ACTIVE',55,NULL) on conflict (rule_id) do nothing;
