insert into articles (title,category,cover_image_url,content_type,panel_images_folder,published,body_content) values ('โรคมือเท้าปากในเด็ก พ่อแม่ควรรู้ อาการเป็นอย่างไร ติดต่อได้อย่างไร และเมื่อไหร่ควรรีบพบแพทย์',NULL,'https://lh3.googleusercontent.com/d/1PubPF7c-w1j-MU9OcajmVVJrux-rdFLr','article',NULL,true,'# โรคมือเท้าปากในเด็ก พ่อแม่ควรรู้ อาการเป็นอย่างไร ติดต่อได้อย่างไร และเมื่อไหร่ควรรีบพบแพทย์โรคมือเท้าปากเป็นโรคติดเชื้อไวรัสที่พบได้บ่อยในเด็กเล็ก โดยเฉพาะเด็กอายุต่ำกว่า 5 ปี และมักพบการระบาดในสถานที่ที่มีเด็กรวมตัวกัน เช่น โรงเรียนอนุบาล ศูนย์พัฒนาเด็กเล็ก หรือสถานรับเลี้ยงเด็ก โรคนี้สามารถติดต่อกันได้ง่ายจากการสัมผัสสารคัดหลั่ง น้ำลาย น้ำมูก น้ำจากตุ่มพอง รวมถึงอุจจาระของผู้ติดเชื้อโดยทั่วไปโรคมือเท้าปากมักไม่รุนแรงและเด็กส่วนใหญ่สามารถหายได้เอง แต่ในบางรายอาจเกิดภาวะแทรกซ้อนรุนแรงได้ ดังนั้นสิ่งที่พ่อแม่ควรรู้ไม่ใช่เพียงว่า "ลูกมีตุ่มที่มือหรือเท้าหรือไม่" แต่ควรเข้าใจลักษณะอาการ การดูแลเด็ก การป้องกันการแพร่เชื้อ และที่สำคัญคือการสังเกตสัญญาณอันตรายที่ควรพาเด็กไปพบแพทย์## โรคมือเท้าปากคืออะไร?โรคมือเท้าปาก หรือ Hand, Foot, and Mouth Disease (HFMD) เป็นโรคติดเชื้อไวรัสในกลุ่ม Enterovirus พบได้บ่อยในเด็กเล็ก โดยเฉพาะเด็กที่มีอายุต่ำกว่า 5 ปี แม้ว่าเด็กโต วัยรุ่น และผู้ใหญ่ก็สามารถติดเชื้อได้เช่นกันหลังจากได้รับเชื้อ เด็กอาจเริ่มมีอาการหลังผ่านไปประมาณ 3–5 วัน โดยอาการที่พบได้บ่อย ได้แก่ ไข้ เจ็บคอ เบื่ออาหาร อ่อนเพลีย และต่อมาอาจมีแผลหรือตุ่มในช่องปาก รวมถึงผื่นหรือตุ่มบริเวณมือและเท้าชื่อ "โรคมือเท้าปาก" อาจทำให้หลายคนเข้าใจว่าเด็กทุกคนจะต้องมีผื่นหรือตุ่มครบทั้งมือ เท้า และปาก แต่ในความเป็นจริงอาการของเด็กแต่ละคนอาจแตกต่างกัน บางคนมีผื่นเพียงเล็กน้อย บางคนมีแผลในปากเด่นชัด ขณะที่บางรายอาจมีอาการไม่มากจนผู้ปกครองสังเกตได้ยากโรคส่วนใหญ่มักมีอาการไม่รุนแรงและค่อย ๆ ดีขึ้นภายในประมาณ 7–10 วัน อย่างไรก็ตาม เด็กบางรายอาจมีภาวะแทรกซ้อนที่รุนแรง โดยเฉพาะการติดเชื้อไวรัสบางสายพันธุ์ เช่น Enterovirus 71 หรือ EV71 ซึ่งอาจเกี่ยวข้องกับภาวะแทรกซ้อนทางระบบประสาทและหัวใจได้ แม้จะพบไม่บ่อยก็ตาม## ลูกเป็นมือเท้าปาก อาการเริ่มต้นเป็นอย่างไร?อาการของโรคมือเท้าปากอาจเริ่มจากอาการที่ดูคล้ายกับการติดเชื้อไวรัสทั่วไป เด็กอาจมีไข้ เจ็บคอ อ่อนเพลีย หรือดูงอแงมากกว่าปกติสิ่งหนึ่งที่พ่อแม่อาจสังเกตได้คือ เด็กเริ่มกินอาหารหรือนมได้น้อยลง โดยเฉพาะในเด็กที่สามารถบอกอาการได้ อาจบอกว่าเจ็บปากหรือเจ็บคอเมื่อสังเกตภายในช่องปาก อาจพบจุดแดง ตุ่ม หรือแผลบริเวณลิ้น เหงือก กระพุ้งแก้ม หรือเพดานปาก แผลเหล่านี้อาจทำให้เด็กรู้สึกเจ็บมากขึ้นเมื่อกินอาหารหรือดื่มน้ำ เด็กบางคนจึงอาจมีน้ำลายไหลมากขึ้น งอแง หรือปฏิเสธอาหารและน้ำหลังจากนั้นอาจพบผื่นหรือตุ่มบริเวณฝ่ามือ ฝ่าเท้า นิ้วมือ หรือนิ้วเท้า และอาจพบผื่นบริเวณก้นหรือส่วนอื่นของร่างกายร่วมด้วยดังนั้น หากลูกมีไข้ร่วมกับอาการเจ็บปาก มีแผลในปาก หรือมีผื่นและตุ่มผิดปกติ ควรสังเกตอาการอย่างใกล้ชิด และหากไม่แน่ใจควรให้แพทย์ตรวจประเมิน## โรคมือเท้าปากติดต่อกันได้อย่างไร?โรคมือเท้าปากสามารถแพร่กระจายได้ง่าย โดยเฉพาะในสถานที่ที่มีเด็กอยู่รวมกันเป็นจำนวนมากเชื้อสามารถแพร่ผ่านน้ำลาย น้ำมูก ละอองจากการไอหรือจาม น้ำจากตุ่มพอง รวมถึงอุจจาระของผู้ติดเชื้อ นอกจากนี้เชื้อยังสามารถแพร่ผ่านมือ ของเล่น และพื้นผิวที่มีการปนเปื้อนเชื้อได้อีกด้วยเด็กเล็กเป็นกลุ่มที่มีโอกาสแพร่เชื้อได้ง่าย เนื่องจากมักเล่นใกล้ชิดกัน ใช้ของเล่นร่วมกัน และอาจนำมือหรือสิ่งของเข้าปากเป็นประจำสิ่งที่พ่อแม่ควรรู้คือ ผู้ติดเชื้อบางรายอาจมีอาการเพียงเล็กน้อยหรือแทบไม่มีอาการ แต่ยังสามารถแพร่เชื้อได้ ดังนั้นการป้องกันจึงควรเน้นเรื่องสุขอนามัยและการลดการแพร่กระจายของเชื้อ ไม่ใช่เพียงการแยกเด็กที่มีตุ่มให้เห็นชัดเจนเท่านั้น## ถ้าลูกเป็นมือเท้าปาก ควรดูแลอย่างไร?โรคมือเท้าปากส่วนใหญ่ไม่มีการรักษาด้วยยาต้านไวรัสจำเพาะ การรักษาจึงมุ่งเน้นไปที่การดูแลตามอาการและป้องกันภาวะแทรกซ้อนสิ่งที่สำคัญที่สุดอย่างหนึ่งคือการดูแลให้เด็กได้รับน้ำและของเหลวอย่างเพียงพอ เพราะแผลในปากอาจทำให้เด็กเจ็บจนไม่อยากกินอาหารหรือดื่มน้ำพ่อแม่ควรสังเกตว่าเด็กยังสามารถดื่มน้ำหรือนมได้หรือไม่ และควรติดตามการปัสสาวะ หากเด็กดื่มได้น้อยมาก ปัสสาวะน้อยลง หรือมีอาการซึมลง ควรรีบปรึกษาแพทย์หากเด็กเจ็บปากมาก อาจเลือกอาหารที่รับประทานง่ายและเหมาะกับวัยของเด็ก โดยให้เด็กได้รับของเหลวทีละน้อยแต่บ่อยครั้งตามความเหมาะสมหากจำเป็นต้องใช้ยาเพื่อลดไข้หรือบรรเทาอาการเจ็บ ควรใช้ยาตามคำแนะนำของแพทย์หรือบุคลากรทางการแพทย์ และควรคำนึงถึงอายุและน้ำหนักตัวของเด็ก ไม่ควรให้ยาแอสไพรินแก่เด็ก## ลูกเป็นมือเท้าปาก ต้องหยุดเรียนหรือไม่?เมื่อเด็กป่วย ควรให้เด็กพักอยู่ที่บ้านและหลีกเลี่ยงการไปโรงเรียนหรือสถานรับเลี้ยงเด็กในช่วงที่ยังมีอาการ เพื่อช่วยลดโอกาสแพร่เชื้อไปยังเด็กคนอื่นพ่อแม่ควรปฏิบัติตามคำแนะนำของแพทย์และนโยบายของสถานศึกษาเกี่ยวกับการกลับไปเรียนนอกจากการให้เด็กพักอยู่บ้านแล้ว ควรทำความสะอาดของเล่นและพื้นผิวที่เด็กสัมผัสบ่อย รวมถึงแยกของใช้ส่วนตัวที่อาจสัมผัสน้ำลายหรือสารคัดหลั่งของเด็กสมาชิกในครอบครัวควรล้างมือด้วยน้ำและสบู่อย่างสม่ำเสมอ โดยเฉพาะหลังเข้าห้องน้ำ หลังเปลี่ยนผ้าอ้อม ก่อนรับประทานอาหาร และหลังดูแลเด็กที่ป่วย## อาการแบบไหนที่ควรรีบพาลูกไปพบแพทย์?แม้โรคมือเท้าปากส่วนใหญ่จะไม่รุนแรง แต่พ่อแม่ควรสังเกตอาการของลูกอย่างใกล้ชิดหากเด็กมีอาการซึมลงผิดปกติ ดื่มน้ำหรือนมไม่ได้ กินได้น้อยมาก อาเจียนมากหรืออาเจียนบ่อย หรือมีอาการที่บ่งชี้ว่าอาจเกิดภาวะขาดน้ำ ควรพาไปพบแพทย์เพื่อประเมินนอกจากนี้ หากเด็กมีอาการทางระบบประสาท เช่น ชัก แขนขาอ่อนแรง มีอาการกระตุก หรือมีความผิดปกติของการเคลื่อนไหว รวมถึงมีอาการหายใจผิดปกติหรือหอบเหนื่อย ควรรีบไปโรงพยาบาลทันทีสิ่งสำคัญคือ พ่อแม่ไม่ควรรอให้มีผื่นหรือตุ่มเพิ่มขึ้นจึงค่อยพาเด็กไปพบแพทย์ หากอาการโดยรวมของเด็กแย่ลง หรือเด็กดูไม่เหมือนปกติ ควรได้รับการประเมินจากแพทย์## ป้องกันโรคมือเท้าปากอย่างไร?การป้องกันโรคมือเท้าปากเน้นที่การลดโอกาสการแพร่กระจายของเชื้อและรักษาสุขอนามัยควรสอนเด็กให้ล้างมือด้วยน้ำและสบู่เป็นประจำ โดยเฉพาะหลังเข้าห้องน้ำ หลังเปลี่ยนผ้าอ้อม ก่อนรับประทานอาหาร และหลังเล่นหรือสัมผัสสิ่งของที่อาจปนเปื้อนควรหลีกเลี่ยงการใช้แก้วน้ำ ช้อนส้อม ผ้าเช็ดตัว หรือของใช้ส่วนตัวร่วมกัน และควรทำความสะอาดของเล่น พื้นผิว และสิ่งของที่เด็กใช้ร่วมกันอย่างสม่ำเสมอหากมีเด็กในบ้านป่วย ควรลดการสัมผัสใกล้ชิดกับสมาชิกคนอื่นเท่าที่ทำได้ และเพิ่มความระมัดระวังเรื่องการล้างมือและการทำความสะอาดสิ่งของสิ่งที่พ่อแม่ควรจำไว้คือ การป้องกันโรคมือเท้าปากไม่ได้หมายถึงการป้องกันเด็กไม่ให้สัมผัสผู้อื่นเพียงอย่างเดียว แต่ต้องควบคู่ไปกับการสร้างสุขนิสัยที่ดี โดยเฉพาะการล้างมือและการทำความสะอาดสิ่งของที่เด็กใช้ร่วมกัน## สรุป: มือเท้าปากไม่ใช่โรคที่ต้องตื่นตระหนก แต่ต้องรู้จักสังเกตโรคมือเท้าปากเป็นโรคที่พบได้บ่อยในเด็กเล็ก และในเด็กส่วนใหญ่มักหายได้เองโดยไม่มีภาวะแทรกซ้อนรุนแรงสิ่งที่พ่อแม่ควรให้ความสำคัญคือการสังเกตอาการของลูก โดยเฉพาะไข้ แผลในปาก ผื่นหรือตุ่ม และความสามารถในการกินหรือดื่มน้ำในช่วงที่เด็กป่วย ควรดูแลเรื่องการได้รับน้ำอย่างเพียงพอ พักผ่อน และป้องกันการแพร่เชื้อไปยังผู้อื่นหากลูกมีอาการซึมลง ดื่มน้ำไม่ได้ อาเจียนมาก ชัก หายใจผิดปกติ หรือมีอาการผิดปกติที่น่ากังวล ควรรีบพาไปพบแพทย์เพราะสำหรับโรคมือเท้าปาก สิ่งที่สำคัญที่สุดไม่ใช่เพียงการดูว่า "มีตุ่มหรือไม่" แต่คือการดูว่า **ลูกมีอาการโดยรวมเป็นอย่างไร และกำลังดีขึ้นหรือแย่ลง**---### บ้านเด็กคลินิกหากลูกมีไข้ มีแผลในปาก มีผื่นหรือตุ่มผิดปกติ หรือผู้ปกครองไม่แน่ใจว่าอาการที่พบเข้าข่ายโรคมือเท้าปากหรือไม่ สามารถพาเด็กมาพบกุมารแพทย์เพื่อประเมินอาการและรับคำแนะนำในการดูแลอย่างเหมาะสม**เพราะสุขภาพที่ดีของลูก เริ่มต้นจากการสังเกตและดูแลอย่างเข้าใจ**> **หมายเหตุ:** ข้อมูลนี้จัดทำขึ้นเพื่อให้ความรู้เบื้องต้น ไม่สามารถใช้แทนการตรวจวินิจฉัยโดยแพทย์ได้ หากเด็กมีอาการรุนแรงหรืออาการแย่ลง ควรรีบพบแพทย์');
