insert into team (name,role,photo_url,credentials,display_order,active) values ('หมอเอ๋ (พญ. กัลยา สุดกรยุทธ์)','กุมารแพทย์','https://lh3.googleusercontent.com/d/12fleaq2K34GhGvO7lkc-CaM9GmZR6rEw','สถานะความรู้ความชำนาญเฉพาะทางที่แพทยสภารับรองสาขา กุมารเวชศาสตร์ ( Pediatrics )สาขา เวชศาสตร์ครอบครัว ( Family Medicine )อนุสาขา กุมารเวชศาสตร์ประสาทวิทยา ( Pediatric Neurology )',1,true);
