insert into reviews (source,reviewer_name,text,rating,screenshot_url,permission_confirmed,review_count) values ('Google',NULL,'ผู้ปกครองส่วนใหญ่ให้คะแนนคลินิกบ้านเด็ก 5 ดาวเต็ม ชื่นชมความใส่ใจของคุณหมอ การอธิบายอย่างละเอียด ความใจดีที่ทำให้เด็กๆ ไม่กลัว และการฉีดวัคซีนที่แทบไม่เจ็บ',5,'https://www.google.com/maps/place/คลินิกบ้านเด็ก+(BaandeK+Clinic)+:+คลินิกเวชกรรมเฉพาะทางด้านกุมารเวชกรรม/@9.1533668,99.3568898,19z/data=!4m8!3m7!1s0x305407d874174a43:0x5f2526dbcfa9afc8!8m2!3d9.1533433!4d99.3572274!9m1!1b1!16s%2Fg%2F11kqrqh_vc',true,9);
insert into vaccine_news (vaccine_name,start_date,end_date,status,description) values ('วัคซีน PCV (นิวโมคอคคัส ชนิดคอนจูเกต)','2026-10-01',NULL,true,'ข่าวดี! วัคซีน PCV เข้าสิทธิบัตรทอง ฉีดฟรี 3 เข็ม เริ่ม 1 ต.ค. 69 — สปสช. (บัตรทอง) ประกาศเพิ่มวัคซีนป้องกันโรคติดเชื้อนิวโมคอคคัส (PCV) เข้าเป็นสิทธิประโยชน์ฟรีสำหรับเด็กไทย ครอบคลุมเด็กอายุ 2 เดือน–12 เดือน ฉีดฟรี 3 เข็ม (เข็มที่ 1 อายุ 2 เดือน, เข็มที่ 2 อายุ 4 เดือน, เข็มที่ 3 อายุ 12 เดือน) มีผลตั้งแต่ 1 ตุลาคม 2569 เป็นต้นไป ⚠️ ข้อควรทราบ: สิทธิ์ฉีดฟรีนี้ใช้ได้เฉพาะสถานพยาบาลในระบบบัตรทองเท่านั้น สำหรับบ้านเด็กคลินิก ยังคงเป็นวัคซีนทางเลือกแบบเสียค่าใช้จ่ายตามปกติ สอบถามเพิ่มเติมได้ที่ทีมบ้านเด็กคลินิก (ที่มา: ราชกิจจานุเบกษา 20 กรกฎาคม 2569)');
insert into vaccine_news (vaccine_name,start_date,end_date,status,description) values ('วัคซีน PCV14 (ทางเลือกใหม่ในกลุ่ม PCV/IPD)','เร็วๆ นี้',NULL,true,'บ้านเด็กคลินิก มีแผนเพิ่มวัคซีน PCV14 (วัคซีนป้องกันโรคติดเชื้อนิวโมคอคคัส ชนิดคอนจูเกต 14 สายพันธุ์) เป็นอีกหนึ่งทางเลือกในกลุ่มวัคซีน PCV/IPD เร็วๆ นี้ เพื่อเพิ่มทางเลือกในการป้องกันโรคติดเชื้อนิวโมคอคคัสให้เด็กๆ ครอบคลุมสายพันธุ์มากขึ้น สอบถามรายละเอียดเพิ่มเติมหรือนัดปรึกษาได้ที่บ้านเด็กคลินิก');
